('ქვეყნის ასარჩევი სია','select კომპაქტურ არჩევანს უზრუნველყოფს; ცარიელი საწყისი option არჩევის საჭიროებას აჩვენებს.','<label for="country">ქვეყანა</label><select id="country" name="country" required><option value="">აირჩიე ქვეყანა</option><option value="GE">საქართველო</option><option value="DE">გერმანია</option></select>'),
('დაჯგუფებული ვარიანტები','optgroup გრძელ არჩევანს თემატურად ყოფს.','<label for="topic">თემა</label><select id="topic"><optgroup label="სტრუქტურა"><option>სემანტიკა</option><option>ფორმები</option></optgroup><optgroup label="დიზაინი"><option>Grid</option><option>ტიპოგრაფია</option></optgroup></select>'),
