('უსაფრთხო შეყვანის სიგანე','min-width ნული მოქნილ ბლოკში ველის შეკუმშვას უშვებს.','.search { display:flex; gap:12px; } input { min-width:0; flex:1; }','<form class="search"><label for="s">ძიება</label><input id="s"><button>იპოვე</button></form>'),
