('მართვის ღილაკების უსაფრთხო დაშორება','gap კონტროლებს შემთხვევითი ერთმანეთზე დაჭერისგან იცავს.','.controls { display:flex; gap:12px; flex-wrap:wrap; } .controls button { min-height:44px; }','<div class="controls"><button>წინა</button><button>შემდეგი</button></div>'),
